import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except Exception:
        return v is None


def _attrs_differ(a, b):
    """Null-aware inequality: NaN vs NaN -> not different; NaN vs value -> different."""
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _get_input(inputs: dict, *candidates):
    for c in candidates:
        if c in inputs:
            return inputs[c]
    # try case-insensitive match
    lower_map = {k.lower(): k for k in inputs.keys()}
    for c in candidates:
        if c.lower() in lower_map:
            return inputs[lower_map[c.lower()]]
    raise KeyError(f"None of {candidates} found in inputs keys {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_CUSTOMER", "dim_customer").copy()
    stg = _get_input(inputs, "STG_CUSTOMER", "stg_customer").copy()

    # Ensure dim has expected columns even if empty input
    for col in ["customer_id", "name", "segment", "eff_start_date", "eff_end_date", "is_current"]:
        if col not in dim.columns:
            dim[col] = pd.Series(dtype="object")

    # ---- Step 1: deduplicate staging to latest record per customer_id ----
    # Tie-break: greater (name, segment) lexicographically wins on equal update_date.
    if len(stg) > 0:
        stg_sorted = stg.sort_values(
            by=["update_date", "name", "segment"],
            ascending=[False, False, False],
            kind="mergesort",
        )
        # IMPORTANT: use drop_duplicates (keep first full row) rather than
        # groupby().first(), which aggregates per-column first NON-NULL
        # value independently and can mix values from different rows when
        # nulls are present, corrupting the (name, segment) pairing.
        stg_dedup = stg_sorted.drop_duplicates(subset="customer_id", keep="first").reset_index(drop=True)
    else:
        stg_dedup = stg.copy()

    dim = dim.reset_index(drop=True)

    new_rows = []

    for _, s in stg_dedup.iterrows():
        cid = s["customer_id"]
        mask_current = (dim["customer_id"] == cid) & (dim["is_current"] == 1)
        current_idx = dim.index[mask_current]

        if len(current_idx) == 0:
            # No current row exists -> insert new version
            new_rows.append({
                "customer_id": cid,
                "name": s["name"],
                "segment": s["segment"],
                "eff_start_date": s["update_date"],
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
        else:
            # Take the first current row (legacy assumes a single current row)
            c = dim.loc[current_idx[0]]

            changed = _attrs_differ(c["name"], s["name"]) or _attrs_differ(c["segment"], s["segment"])

            if changed:
                # Expire current row(s)
                dim.loc[current_idx, "eff_end_date"] = s["update_date"]
                dim.loc[current_idx, "is_current"] = 0

                # Insert new current version
                new_rows.append({
                    "customer_id": cid,
                    "name": s["name"],
                    "segment": s["segment"],
                    "eff_start_date": s["update_date"],
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: no change -> do nothing

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=["customer_id", "name", "segment",
                                                   "eff_start_date", "eff_end_date", "is_current"])
        dim = pd.concat([dim, new_df], ignore_index=True)

    dim = dim.reset_index(drop=True)

    return {"dim_customer_out": dim}
